-- ============================================================
-- 205: authentication trust boundary, multiple passkeys, action-bound step-up, recovery
--
-- THREAT   (before 205) Anyone with the control_app password could call api_login_complete(challenge,
--          credential_id, counter) and receive an owner session with NO passkey; satisfy any step-up the same
--          way; claim the owner identity before enrolment (api_bootstrap_owner); and disable real credentials
--          by sending a low counter. See docs/SECURITY_FINDINGS.md S-1.
-- CHANGES  1. Challenges are generated BY THE DATABASE (32 random bytes). The app cannot choose them.
--          2. Sessions, step-up grants and new credentials are created only from RAW WebAuthn evidence that
--             the database verifies itself (204): clientDataJSON type/challenge/origin/crossOrigin,
--             authenticatorData RP ID hash, UP+UV flags, signature counter, ES256 signature with the stored key.
--             No function accepts a "verified" flag or a counter from the caller.
--          3. A new owner role, control_auth (NOLOGIN), owns identities, credentials, challenges, sessions,
--             grants, tokens and recovery requests, and every function that touches them. control_definer
--             (tenant + audit API) loses all access to those tables; it may only call session_resolve() and
--             stepup_consume().
--          4. Step-up is a single-use GRANT bound to (session, action, target), valid 2 minutes, instead of a
--             5-minute blanket window. A step-up for one action cannot authorise another, or the same one twice.
--          5. Owner bootstrap and recovery requests are host-only functions (no grant to any login role:
--             only the database superuser, i.e. the infrastructure owner on the host, can call them).
--          6. Operators can hold several passkeys (max 10). Adding or revoking one needs a fresh step-up bound
--             to that action; the final usable passkey cannot be revoked (serialised by an identity row lock).
--          7. Lost-device recovery needs TWO people: a host-side request (superuser) AND approval by a different
--             active owner with a step-up bound to that request. Single-owner installs cannot recover; that is
--             a documented owner decision (docs/RECOVERY.md), not a bypass.
-- COMPAT   All open sessions are revoked (reason 'upgrade'). Credentials whose stored key is not canonical
--          ES256 are disabled. The audit chain is untouched.
-- ROLLBACK Not supported in place (privilege model change). Restore from the pre-205 recovery point.
-- ============================================================

-- ------------------------------------------------------------ role
DO $r$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'control_auth') THEN
    CREATE ROLE control_auth NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;
  END IF;
END
$r$;
GRANT USAGE ON SCHEMA control TO control_auth;
GRANT USAGE ON SCHEMA control_ext TO control_auth;
GRANT CREATE ON SCHEMA control TO control_auth;
ALTER DEFAULT PRIVILEGES FOR ROLE control_auth IN SCHEMA control REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;

-- ------------------------------------------------------------ settings (definer-owned; no write API exists)
INSERT INTO control.settings (key, value) VALUES
  ('webauthn_rp_id',                 '"localhost"'),
  ('webauthn_origin',                '"http://localhost:3410"'),
  ('stepup_grant_ttl_seconds',       '120'),
  ('max_credentials_per_identity',   '10'),
  ('recovery_request_ttl_seconds',   '86400'),
  ('recovery_token_ttl_seconds',     '1800');
DELETE FROM control.settings WHERE key = 'stepup_max_age_seconds';

SET ROLE control_definer;
CREATE FUNCTION control.setting_text(p_key text) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = control, pg_temp AS $$
  SELECT value #>> '{}' FROM control.settings WHERE key = p_key
$$;
CREATE OR REPLACE FUNCTION control.api_contract_version() RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = control, pg_temp AS $$
  SELECT 'orvix-control/0.2'::text
$$;
RESET ROLE;

