-- ------------------------------------------------------------ schema changes
ALTER TABLE control.webauthn_challenges DROP CONSTRAINT webauthn_challenges_purpose_check;
ALTER TABLE control.webauthn_challenges ADD CONSTRAINT webauthn_challenges_purpose_check
  CHECK (purpose IN ('register', 'register_add', 'login', 'stepup', 'anchor'));
ALTER TABLE control.webauthn_challenges ADD COLUMN action text, ADD COLUMN target text;

ALTER TABLE control.enrolment_tokens DROP CONSTRAINT enrolment_tokens_purpose_check;
ALTER TABLE control.enrolment_tokens ADD CONSTRAINT enrolment_tokens_purpose_check
  CHECK (purpose IN ('owner_bootstrap', 'recovery'));

ALTER TABLE control.webauthn_credentials
  ADD COLUMN nickname    text CHECK (nickname IS NULL OR length(nickname) BETWEEN 1 AND 60),
  ADD COLUMN created_via text NOT NULL DEFAULT 'bootstrap' CHECK (created_via IN ('bootstrap', 'added', 'recovery')),
  ADD COLUMN disabled_by uuid;

ALTER TABLE control.sessions DROP CONSTRAINT sessions_revoke_reason_check;
ALTER TABLE control.sessions ADD CONSTRAINT sessions_revoke_reason_check
  CHECK (revoke_reason IN ('logout', 'idle_timeout', 'absolute_timeout', 'identity_inactive', 'admin',
                           'credential_revoked', 'recovery', 'upgrade'));

SET ROLE control_auth;

CREATE TABLE control.stepup_grants (
  id              bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  session_id_hash bytea NOT NULL,
  identity_id     uuid NOT NULL REFERENCES control.platform_identities(id),
  credential_id   text NOT NULL,
  action          text NOT NULL,
  target          text NOT NULL,
  created_at      timestamptz NOT NULL DEFAULT now(),
  expires_at      timestamptz NOT NULL,
  used_at         timestamptz
);
CREATE INDEX stepup_grants_lookup ON control.stepup_grants (session_id_hash, action, target) WHERE used_at IS NULL;
ALTER TABLE control.stepup_grants ENABLE ROW LEVEL SECURITY;

CREATE TABLE control.recovery_requests (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  subject_id       uuid NOT NULL REFERENCES control.platform_identities(id),
  reason           text NOT NULL CHECK (length(btrim(reason)) BETWEEN 10 AND 500),
  state            text NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'approved', 'redeemed', 'cancelled')),
  requested_at     timestamptz NOT NULL DEFAULT now(),
  expires_at       timestamptz NOT NULL,
  approved_by      uuid REFERENCES control.platform_identities(id),
  approved_at      timestamptz,
  redeemed_at      timestamptz,
  CHECK (approved_by IS NULL OR approved_by <> subject_id)
);
CREATE UNIQUE INDEX recovery_requests_one_open ON control.recovery_requests (subject_id) WHERE state IN ('pending', 'approved');
ALTER TABLE control.recovery_requests ENABLE ROW LEVEL SECURITY;

ALTER TABLE control.enrolment_tokens ADD COLUMN recovery_request_id uuid REFERENCES control.recovery_requests(id);

RESET ROLE;

