-- ============================================================ auth functions (owner control_auth)
SET ROLE control_auth;

-- Issues a database-generated challenge. Only its SHA-256 is stored. p_fixed is used only for 'anchor'
-- challenges, which are derived from the anchored head so the signature commits to it (206).
CREATE FUNCTION control.challenge_issue(p_purpose text, p_identity uuid, p_session_hash bytea,
                                        p_action text, p_target text, p_fixed text DEFAULT NULL)
RETURNS text
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE v text;
BEGIN
  IF p_fixed IS NOT NULL AND p_purpose <> 'anchor' THEN
    RAISE EXCEPTION 'fixed challenges are only allowed for anchors';
  END IF;
  v := coalesce(p_fixed, control.b64url_encode(decode(control.new_secret(), 'hex')));
  INSERT INTO control.webauthn_challenges (challenge_hash, purpose, identity_id, session_id_hash, action, target, expires_at)
  VALUES (control.sha(v), p_purpose, p_identity, p_session_hash, p_action, p_target,
          now() + make_interval(secs => control.setting_int('challenge_ttl_seconds')));
  RETURN v;
END
$$;

-- Consumes a challenge exactly once (burned even when the purpose does not match).
CREATE FUNCTION control.challenge_consume(p_challenge text, p_purpose text)
RETURNS control.webauthn_challenges
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE v control.webauthn_challenges;
BEGIN
  IF p_challenge IS NULL OR p_challenge !~ '^[A-Za-z0-9_-]{32,128}$' THEN RETURN NULL; END IF;
  UPDATE control.webauthn_challenges SET used_at = now()
   WHERE challenge_hash = control.sha(p_challenge) AND used_at IS NULL
  RETURNING * INTO v;
  IF v.challenge_hash IS NULL OR v.purpose <> p_purpose OR v.expires_at <= now() THEN
    RETURN NULL;
  END IF;
  RETURN v;
END
$$;

-- Parses and checks clientDataJSON. NULL unless it is a JSON object with the expected type, the configured
-- origin, a string challenge, no cross-origin flag and no topOrigin.
CREATE FUNCTION control.wa_client_data(p bytea, p_type text) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE cd jsonb;
BEGIN
  IF p IS NULL OR length(p) > 4096 THEN RETURN NULL; END IF;
  BEGIN
    cd := convert_from(p, 'UTF8')::jsonb;
  EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
  END;
  IF jsonb_typeof(cd) IS DISTINCT FROM 'object'
     OR cd ->> 'type' IS DISTINCT FROM p_type
     OR cd ->> 'origin' IS DISTINCT FROM control.setting_text('webauthn_origin')
     OR jsonb_typeof(cd -> 'challenge') IS DISTINCT FROM 'string'
     OR coalesce(cd -> 'crossOrigin', 'false'::jsonb) <> 'false'::jsonb
     OR cd ? 'topOrigin' THEN
    RETURN NULL;
  END IF;
  RETURN cd;
END
$$;

-- Verifies an assertion end to end. Consumes the challenge first (single use, even on failure).
-- err IS NULL means: challenge issued by the DB for p_purpose, unexpired, unused, bound to p_session_hash
-- (NULL for login); clientDataJSON type/origin OK; RP ID hash OK; UP and UV set; credential active and
-- belonging to the challenge's identity (if bound); identity active; ES256 signature over
-- authenticatorData || SHA-256(clientDataJSON) valid; signature counter strictly increasing (or 0/0).
CREATE FUNCTION control.wa_assertion(p_purpose text, p_cred text, p_cdj bytea, p_ad bytea, p_sig bytea,
                                     p_session_hash bytea,
                                     OUT err text, OUT identity_id uuid, OUT ch control.webauthn_challenges)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE cd jsonb; c control.webauthn_credentials; i control.platform_identities; v_flags integer; v_count bigint;
BEGIN
  cd := control.wa_client_data(p_cdj, 'webauthn.get');
  IF cd IS NULL THEN err := 'BAD_CLIENT_DATA'; RETURN; END IF;
  ch := control.challenge_consume(cd ->> 'challenge', p_purpose);
  IF ch.challenge_hash IS NULL OR ch.session_id_hash IS DISTINCT FROM p_session_hash THEN
    err := 'INVALID_CHALLENGE'; RETURN;
  END IF;
  SELECT * INTO c FROM control.webauthn_credentials WHERE credential_id = p_cred FOR UPDATE;
  IF c.id IS NULL OR c.disabled_at IS NOT NULL THEN err := 'UNKNOWN_CREDENTIAL'; RETURN; END IF;
  identity_id := c.identity_id;
  SELECT * INTO i FROM control.platform_identities WHERE id = c.identity_id;
  IF i.state <> 'active' THEN err := 'IDENTITY_INACTIVE'; RETURN; END IF;
  IF ch.identity_id IS NOT NULL AND ch.identity_id <> c.identity_id THEN err := 'CREDENTIAL_IDENTITY_MISMATCH'; RETURN; END IF;
  IF p_ad IS NULL OR length(p_ad) < 37 OR length(p_ad) > 1024 THEN err := 'BAD_AUTHENTICATOR_DATA'; RETURN; END IF;
  IF substring(p_ad FROM 1 FOR 32) <> sha256(convert_to(control.setting_text('webauthn_rp_id'), 'UTF8')) THEN
    err := 'RP_ID_MISMATCH'; RETURN;
  END IF;
  v_flags := get_byte(p_ad, 32);
  IF v_flags & 1 = 0 OR v_flags & 4 = 0 THEN err := 'USER_NOT_VERIFIED'; RETURN; END IF;
  IF v_flags & 64 <> 0 OR (v_flags & 128 = 0 AND length(p_ad) <> 37) THEN err := 'BAD_AUTHENTICATOR_DATA'; RETURN; END IF;
  v_count := control.b2n(substring(p_ad FROM 34 FOR 4))::bigint;
  IF NOT control.es256_verify(c.public_key, p_ad || sha256(p_cdj), p_sig) THEN
    err := 'SIGNATURE_INVALID'; RETURN;
  END IF;
  -- A validly signed but non-increasing counter means a cloned authenticator: disable it.
  IF (c.sign_count > 0 OR v_count > 0) AND v_count <= c.sign_count THEN
    UPDATE control.webauthn_credentials SET disabled_at = now(), disabled_reason = 'sign_count_regression' WHERE id = c.id;
    PERFORM control.audit_append('platform_identity', i.id, i.display_name, 'platform.credential_disabled', 'success',
      'credential', c.id::text, NULL, 'COUNTER_REGRESSION', '{}'::jsonb);
    err := 'COUNTER_REGRESSION'; RETURN;
  END IF;
  UPDATE control.webauthn_credentials SET sign_count = v_count, last_used_at = now() WHERE id = c.id;
END
$$;

-- Verifies a registration (attestation format "none" only; ES256 key only). Consumes the challenge first.
CREATE FUNCTION control.wa_registration(p_purpose text, p_att bytea, p_cdj bytea,
                                        OUT err text, OUT ch control.webauthn_challenges,
                                        OUT cred_id text, OUT cose bytea, OUT sign_count bigint)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE
  cd jsonb; hdr bytea := '\xa363666d74646e6f6e656761747453746d74a0686175746844617461'::bytea;
  ad bytea; adlen integer; start integer; v_flags integer; l integer; rest integer;
BEGIN
  cd := control.wa_client_data(p_cdj, 'webauthn.create');
  IF cd IS NULL THEN err := 'BAD_CLIENT_DATA'; RETURN; END IF;
  ch := control.challenge_consume(cd ->> 'challenge', p_purpose);
  IF ch.challenge_hash IS NULL THEN err := 'INVALID_CHALLENGE'; RETURN; END IF;
  -- attestationObject = {"fmt":"none","attStmt":{},"authData":bstr} in CTAP2 canonical order.
  IF p_att IS NULL OR length(p_att) < 30 OR length(p_att) > 2048 OR substring(p_att FROM 1 FOR 28) <> hdr THEN
    err := 'UNSUPPORTED_ATTESTATION'; RETURN;
  END IF;
  IF get_byte(p_att, 28) = 88 THEN        -- 0x58: 1-byte length
    adlen := get_byte(p_att, 29); start := 31;
  ELSIF get_byte(p_att, 28) = 89 THEN     -- 0x59: 2-byte length
    adlen := get_byte(p_att, 29) * 256 + get_byte(p_att, 30); start := 32;
  ELSE
    err := 'UNSUPPORTED_ATTESTATION'; RETURN;
  END IF;
  IF start - 1 + adlen <> length(p_att) THEN err := 'UNSUPPORTED_ATTESTATION'; RETURN; END IF;
  ad := substring(p_att FROM start FOR adlen);
  IF length(ad) < 55 + 16 + 77 THEN err := 'BAD_AUTHENTICATOR_DATA'; RETURN; END IF;
  IF substring(ad FROM 1 FOR 32) <> sha256(convert_to(control.setting_text('webauthn_rp_id'), 'UTF8')) THEN
    err := 'RP_ID_MISMATCH'; RETURN;
  END IF;
  v_flags := get_byte(ad, 32);
  IF v_flags & 1 = 0 OR v_flags & 4 = 0 THEN err := 'USER_NOT_VERIFIED'; RETURN; END IF;
  IF v_flags & 64 = 0 THEN err := 'BAD_AUTHENTICATOR_DATA'; RETURN; END IF;
  sign_count := control.b2n(substring(ad FROM 34 FOR 4))::bigint;
  l := get_byte(ad, 53) * 256 + get_byte(ad, 54);
  IF l < 16 OR l > 1023 OR length(ad) < 55 + l + 77 THEN err := 'BAD_AUTHENTICATOR_DATA'; RETURN; END IF;
  cose := substring(ad FROM 56 + l FOR 77);
  IF control.cose_es256_xy(cose) IS NULL THEN err := 'UNSUPPORTED_KEY'; RETURN; END IF;
  rest := length(ad) - (55 + l + 77);
  IF rest > 0 AND v_flags & 128 = 0 THEN err := 'BAD_AUTHENTICATOR_DATA'; RETURN; END IF;
  cred_id := control.b64url_encode(substring(ad FROM 56 FOR l));
END
$$;

-- Session resolution (unchanged semantics; now owned by control_auth). Granted to control_definer.
CREATE FUNCTION control.session_resolve(p_token text) RETURNS control.session_ctx
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE
  s control.sessions; i control.platform_identities;
  v_idle interval := make_interval(secs => control.setting_int('session_idle_seconds'));
  v_reason text; r control.session_ctx;
BEGIN
  IF p_token IS NULL OR p_token !~ '^[0-9a-f]{64}$' OR v_idle IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO s FROM control.sessions WHERE id_hash = control.sha(p_token) FOR UPDATE;
  IF s.id_hash IS NULL OR s.revoked_at IS NOT NULL THEN RETURN NULL; END IF;
  SELECT * INTO i FROM control.platform_identities WHERE id = s.identity_id;
  IF now() >= s.absolute_expires_at THEN v_reason := 'absolute_timeout';
  ELSIF now() - s.last_seen_at >= v_idle THEN v_reason := 'idle_timeout';
  ELSIF i.state IS DISTINCT FROM 'active' THEN v_reason := 'identity_inactive';
  ELSIF NOT EXISTS (SELECT 1 FROM control.webauthn_credentials c
                     WHERE c.credential_id = s.credential_id AND c.disabled_at IS NULL) THEN v_reason := 'credential_revoked';
  END IF;
  IF v_reason IS NOT NULL THEN
    UPDATE control.sessions SET revoked_at = now(), revoke_reason = v_reason WHERE id_hash = s.id_hash;
    PERFORM control.audit_append('platform_identity', i.id, i.display_name, 'platform.session_expired', 'success',
      'session', encode(substring(s.id_hash FROM 1 FOR 8), 'hex'), NULL, v_reason, '{}'::jsonb);
    RETURN NULL;
  END IF;
  UPDATE control.sessions SET last_seen_at = now() WHERE id_hash = s.id_hash;
  r := (s.id_hash, i.id, i.email, i.display_name, i.role, s.created_at, s.absolute_expires_at, now() + v_idle, NULL);
  RETURN r;
END
$$;

-- Consumes one unused, unexpired step-up grant for exactly (session, identity, action, target).
CREATE FUNCTION control.stepup_consume(c control.session_ctx, p_action text, p_target text) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE v_id bigint;
BEGIN
  IF c.id_hash IS NULL THEN RETURN false; END IF;
  SELECT id INTO v_id FROM control.stepup_grants
   WHERE session_id_hash = c.id_hash AND identity_id = c.identity_id AND action = p_action AND target = p_target
     AND used_at IS NULL AND expires_at > now()
   ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED;
  IF v_id IS NULL THEN RETURN false; END IF;
  UPDATE control.stepup_grants SET used_at = now() WHERE id = v_id;
  RETURN true;
END
$$;

-- ------------------------------------------------------------ host-only: owner bootstrap (no grants)
CREATE FUNCTION control.host_bootstrap_owner(p_email text, p_display_name text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE v_id uuid; v_token text := control.new_secret(); v_email text := lower(btrim(p_email));
BEGIN
  PERFORM pg_advisory_xact_lock(202, 1);
  IF (SELECT closed FROM control.bootstrap_state) OR EXISTS (SELECT 1 FROM control.platform_identities) THEN
    PERFORM control.audit_append('cli', NULL, 'host-bootstrap', 'platform.owner_bootstrap_refused', 'denied',
      NULL, NULL, NULL, 'ALREADY_BOOTSTRAPPED', '{}'::jsonb);
    RETURN control.err('ALREADY_BOOTSTRAPPED');
  END IF;
  BEGIN
    INSERT INTO control.platform_identities (email, display_name, role, state)
    VALUES (v_email, btrim(p_display_name), 'owner', 'enrolling') RETURNING id INTO v_id;
  EXCEPTION WHEN check_violation OR not_null_violation THEN
    RETURN control.err('INVALID_INPUT');
  END;
  INSERT INTO control.enrolment_tokens (token_hash, identity_id, purpose, expires_at)
  VALUES (control.sha(v_token), v_id, 'owner_bootstrap',
          now() + make_interval(secs => control.setting_int('enrolment_token_ttl_seconds')));
  PERFORM control.audit_append('cli', NULL, 'host-bootstrap', 'platform.owner_bootstrap_started', 'success',
    'platform_identity', v_id::text, NULL, NULL, jsonb_build_object('email_domain', split_part(v_email, '@', 2)));
  RETURN jsonb_build_object('ok', true, 'identity_id', v_id, 'enrolment_token', v_token,
                            'expires_in_seconds', control.setting_int('enrolment_token_ttl_seconds'));
END
$$;

-- ------------------------------------------------------------ enrolment by one-time token (bootstrap / recovery)
CREATE FUNCTION control.api_enrol_begin(p_token text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE t control.enrolment_tokens; i control.platform_identities; v_ch text;
BEGIN
  IF NOT control.rate_limit_hit('enrol', 'global', control.setting_int('enrol_token_limit')) THEN
    PERFORM control.audit_append('anonymous', NULL, NULL, 'platform.rate_limited', 'denied', 'endpoint', 'enrol',
      NULL, 'RATE_LIMITED', '{}'::jsonb);
    RETURN control.err('RATE_LIMITED');
  END IF;
  SELECT * INTO t FROM control.enrolment_tokens WHERE p_token ~ '^[0-9a-f]{64}$' AND token_hash = control.sha(p_token);
  IF t.token_hash IS NULL OR t.used_at IS NOT NULL OR t.expires_at <= now() THEN
    PERFORM control.audit_append('anonymous', NULL, NULL, 'platform.enrol_failed', 'denied', NULL, NULL, NULL,
      'INVALID_TOKEN', '{}'::jsonb);
    RETURN control.err('INVALID_TOKEN');
  END IF;
  SELECT * INTO i FROM control.platform_identities WHERE id = t.identity_id;
  IF (t.purpose = 'owner_bootstrap' AND i.state <> 'enrolling') OR (t.purpose = 'recovery' AND i.state <> 'active') THEN
    RETURN control.err('INVALID_TOKEN');
  END IF;
  v_ch := control.challenge_issue('register', i.id, NULL, 'enrol', encode(t.token_hash, 'hex'));
  RETURN jsonb_build_object('ok', true, 'challenge', v_ch, 'identity_id', i.id, 'email', i.email,
    'display_name', i.display_name, 'purpose', t.purpose,
    'exclude_credential_ids', (SELECT coalesce(jsonb_agg(credential_id), '[]'::jsonb) FROM control.webauthn_credentials
                                WHERE identity_id = i.id AND disabled_at IS NULL));
END
$$;

CREATE FUNCTION control.api_enrol_complete(p_token text, p_attestation bytea, p_client_data bytea, p_nickname text)
RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE t control.enrolment_tokens; i control.platform_identities; reg record; v_cred uuid; v_disabled integer; v_sessions integer;
BEGIN
  PERFORM pg_advisory_xact_lock(202, 1);
  SELECT * INTO t FROM control.enrolment_tokens
   WHERE p_token ~ '^[0-9a-f]{64}$' AND token_hash = control.sha(p_token) FOR UPDATE;
  reg := control.wa_registration('register', p_attestation, p_client_data);
  IF t.token_hash IS NULL OR t.used_at IS NOT NULL OR t.expires_at <= now() THEN
    reg.err := 'INVALID_TOKEN';
  ELSIF reg.err IS NULL AND ((reg.ch).identity_id IS DISTINCT FROM t.identity_id
                             OR (reg.ch).action IS DISTINCT FROM 'enrol'
                             OR (reg.ch).target IS DISTINCT FROM encode(t.token_hash, 'hex')) THEN
    reg.err := 'INVALID_CHALLENGE';
  END IF;
  SELECT * INTO i FROM control.platform_identities WHERE id = t.identity_id FOR NO KEY UPDATE;
  IF reg.err IS NULL AND ((t.purpose = 'owner_bootstrap' AND i.state <> 'enrolling')
                          OR (t.purpose = 'recovery' AND i.state <> 'active')) THEN
    reg.err := 'INVALID_TOKEN';
  END IF;
  IF reg.err IS NULL THEN
    BEGIN
      INSERT INTO control.webauthn_credentials (identity_id, credential_id, public_key, sign_count, nickname, created_via)
      VALUES (i.id, reg.cred_id, reg.cose, reg.sign_count, nullif(left(btrim(coalesce(p_nickname, '')), 60), ''),
              CASE t.purpose WHEN 'recovery' THEN 'recovery' ELSE 'bootstrap' END)
      RETURNING id INTO v_cred;
    EXCEPTION WHEN unique_violation OR check_violation THEN
      reg.err := 'INVALID_CREDENTIAL';
    END;
  END IF;
  IF reg.err IS NOT NULL THEN
    PERFORM control.audit_append('anonymous', NULL, NULL, 'platform.enrol_failed', 'denied', NULL, NULL, NULL,
      reg.err, '{}'::jsonb);
    RETURN control.err(reg.err);
  END IF;

  UPDATE control.enrolment_tokens SET used_at = now() WHERE token_hash = t.token_hash;
  IF t.purpose = 'owner_bootstrap' THEN
    UPDATE control.platform_identities SET state = 'active', activated_at = now() WHERE id = i.id;
    UPDATE control.bootstrap_state SET closed = true, closed_at = now();
    PERFORM control.audit_append('platform_identity', i.id, i.display_name, 'platform.owner_enrolled', 'success',
      'credential', v_cred::text, NULL, NULL, '{}'::jsonb);
  ELSE
    -- Recovery: every other passkey of the subject is disabled and every session ends.
    UPDATE control.webauthn_credentials SET disabled_at = now(), disabled_reason = 'recovered'
     WHERE identity_id = i.id AND id <> v_cred AND disabled_at IS NULL;
    GET DIAGNOSTICS v_disabled = ROW_COUNT;
    UPDATE control.sessions SET revoked_at = now(), revoke_reason = 'recovery'
     WHERE identity_id = i.id AND revoked_at IS NULL;
    GET DIAGNOSTICS v_sessions = ROW_COUNT;
    UPDATE control.recovery_requests SET state = 'redeemed', redeemed_at = now() WHERE id = t.recovery_request_id;
    PERFORM control.audit_append('platform_identity', i.id, i.display_name, 'platform.recovery_completed', 'success',
      'recovery_request', t.recovery_request_id::text, NULL, NULL,
      jsonb_build_object('credentials_disabled', v_disabled, 'sessions_revoked', v_sessions, 'new_credential', v_cred));
  END IF;
  RETURN jsonb_build_object('ok', true, 'credential', v_cred);
END
$$;

-- ------------------------------------------------------------ login
CREATE FUNCTION control.api_login_begin() RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
BEGIN
  IF NOT control.rate_limit_hit('login', 'global', control.setting_int('login_global_limit')) THEN
    PERFORM control.audit_append('anonymous', NULL, NULL, 'platform.rate_limited', 'denied', 'endpoint', 'login',
      NULL, 'RATE_LIMITED', '{}'::jsonb);
    RETURN control.err('RATE_LIMITED');
  END IF;
  RETURN jsonb_build_object('ok', true, 'challenge', control.challenge_issue('login', NULL, NULL, NULL, NULL));
END
$$;

-- Public key for the app's own (non-authoritative) pre-check with @simplewebauthn. Public keys are not secret.
CREATE FUNCTION control.api_credential_lookup(p_credential_id text) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = control, pg_temp AS $$
  SELECT coalesce(
    (SELECT jsonb_build_object('ok', true, 'credential_id', c.credential_id, 'public_key', encode(c.public_key, 'base64'),
                               'sign_count', c.sign_count, 'transports', to_jsonb(c.transports))
       FROM control.webauthn_credentials c JOIN control.platform_identities i ON i.id = c.identity_id
      WHERE c.credential_id = p_credential_id AND c.disabled_at IS NULL AND i.state = 'active'),
    control.err('UNKNOWN_CREDENTIAL'))
$$;

CREATE FUNCTION control.api_login_complete(p_credential_id text, p_client_data bytea, p_authenticator_data bytea,
                                           p_signature bytea) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE a record; v_err text; i control.platform_identities; v_token text; v_abs timestamptz;
BEGIN
  IF NOT control.rate_limit_hit('login_credential', coalesce(left(p_credential_id, 64), '-'),
                                control.setting_int('login_credential_limit')) THEN
    v_err := 'RATE_LIMITED';
  ELSE
    a := control.wa_assertion('login', p_credential_id, p_client_data, p_authenticator_data, p_signature, NULL);
    v_err := a.err;
  END IF;
  IF v_err IS NOT NULL THEN
    SELECT pi.* INTO i FROM control.webauthn_credentials c JOIN control.platform_identities pi ON pi.id = c.identity_id
     WHERE c.credential_id = p_credential_id;
    PERFORM control.audit_append(CASE WHEN i.id IS NULL THEN 'anonymous' ELSE 'platform_identity' END,
      i.id, i.display_name, 'platform.login_failed', 'denied', 'credential', left(p_credential_id, 8), NULL, v_err, '{}'::jsonb);
    RETURN control.err(v_err);
  END IF;
  SELECT * INTO i FROM control.platform_identities WHERE id = a.identity_id;
  v_token := control.new_secret();
  v_abs := now() + make_interval(secs => control.setting_int('session_absolute_seconds'));
  INSERT INTO control.sessions (id_hash, identity_id, credential_id, absolute_expires_at)
  VALUES (control.sha(v_token), i.id, p_credential_id, v_abs);
  PERFORM control.audit_append('platform_identity', i.id, i.display_name, 'platform.login_succeeded', 'success',
    'session', encode(substring(control.sha(v_token) FROM 1 FOR 8), 'hex'), NULL, NULL,
    jsonb_build_object('credential', left(p_credential_id, 8)));
  RETURN jsonb_build_object('ok', true, 'session_token', v_token, 'absolute_expires_at', v_abs,
                            'idle_seconds', control.setting_int('session_idle_seconds'));
END
$$;

-- The app reports that its own pre-check failed: burn the challenge and audit. Cannot grant anything.
CREATE FUNCTION control.api_auth_failed(p_purpose text, p_challenge text, p_credential_id text, p_reason text)
RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE i control.platform_identities;
BEGIN
  IF p_purpose NOT IN ('login', 'stepup', 'register', 'register_add', 'anchor') THEN RETURN control.err('INVALID_INPUT'); END IF;
  PERFORM control.challenge_consume(p_challenge, p_purpose);
  SELECT pi.* INTO i FROM control.webauthn_credentials c JOIN control.platform_identities pi ON pi.id = c.identity_id
   WHERE c.credential_id = p_credential_id;
  PERFORM control.audit_append(CASE WHEN i.id IS NULL THEN 'anonymous' ELSE 'platform_identity' END, i.id, i.display_name,
    CASE p_purpose WHEN 'login' THEN 'platform.login_failed' WHEN 'stepup' THEN 'platform.stepup_failed'
                   WHEN 'register_add' THEN 'platform.credential_add_failed' ELSE 'platform.enrol_failed' END,
    'denied', 'credential', left(p_credential_id, 8), NULL,
    left(regexp_replace(coalesce(p_reason, 'VERIFICATION_FAILED'), '[^A-Z_]', '', 'g'), 40), '{}'::jsonb);
  RETURN jsonb_build_object('ok', true);
END
$$;

-- ------------------------------------------------------------ session
CREATE FUNCTION control.api_session_get(p_token text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE c control.session_ctx := control.session_resolve(p_token);
BEGIN
  IF c.identity_id IS NULL THEN RETURN control.err('UNAUTHENTICATED'); END IF;
  RETURN jsonb_build_object('ok', true, 'identity_id', c.identity_id, 'email', c.email, 'display_name', c.display_name,
    'role', c.role, 'absolute_expires_at', c.absolute_expires_at, 'idle_expires_at', c.idle_expires_at,
    'active_credentials', (SELECT count(*) FROM control.webauthn_credentials
                            WHERE identity_id = c.identity_id AND disabled_at IS NULL));
END
$$;

CREATE FUNCTION control.api_session_revoke(p_token text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE c control.session_ctx := control.session_resolve(p_token);
BEGIN
  IF c.identity_id IS NULL THEN RETURN jsonb_build_object('ok', true); END IF;
  UPDATE control.sessions SET revoked_at = now(), revoke_reason = 'logout' WHERE id_hash = c.id_hash;
  UPDATE control.stepup_grants SET used_at = now() WHERE session_id_hash = c.id_hash AND used_at IS NULL;
  PERFORM control.audit_append('platform_identity', c.identity_id, c.display_name, 'platform.logout', 'success',
    'session', encode(substring(c.id_hash FROM 1 FOR 8), 'hex'), NULL, NULL, '{}'::jsonb);
  RETURN jsonb_build_object('ok', true);
END
$$;

-- ------------------------------------------------------------ step-up (single-use, action-bound grants)
CREATE FUNCTION control.api_stepup_begin(p_token text, p_action text, p_target text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE c control.session_ctx := control.session_resolve(p_token);
BEGIN
  IF c.identity_id IS NULL THEN RETURN control.err('UNAUTHENTICATED'); END IF;
  IF p_action NOT IN ('tenant_transition', 'credential_add', 'credential_revoke', 'recovery_approve')
     OR p_target IS NULL OR p_target !~ '^[A-Za-z0-9:_-]{1,200}$' THEN
    RETURN control.err('INVALID_INPUT');
  END IF;
  RETURN jsonb_build_object('ok', true,
    'challenge', control.challenge_issue('stepup', c.identity_id, c.id_hash, p_action, p_target),
    'credential_ids', (SELECT coalesce(jsonb_agg(credential_id), '[]'::jsonb) FROM control.webauthn_credentials
                        WHERE identity_id = c.identity_id AND disabled_at IS NULL));
END
$$;

CREATE FUNCTION control.api_stepup_complete(p_token text, p_credential_id text, p_client_data bytea,
                                            p_authenticator_data bytea, p_signature bytea) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE c control.session_ctx := control.session_resolve(p_token); a record;
BEGIN
  IF c.identity_id IS NULL THEN RETURN control.err('UNAUTHENTICATED'); END IF;
  a := control.wa_assertion('stepup', p_credential_id, p_client_data, p_authenticator_data, p_signature, c.id_hash);
  IF a.err IS NULL AND a.identity_id IS DISTINCT FROM c.identity_id THEN a.err := 'CREDENTIAL_IDENTITY_MISMATCH'; END IF;
  IF a.err IS NOT NULL THEN
    PERFORM control.audit_append('platform_identity', c.identity_id, c.display_name, 'platform.stepup_failed', 'denied',
      'session', encode(substring(c.id_hash FROM 1 FOR 8), 'hex'), NULL, a.err, '{}'::jsonb);
    RETURN control.err(a.err);
  END IF;
  INSERT INTO control.stepup_grants (session_id_hash, identity_id, credential_id, action, target, expires_at)
  VALUES (c.id_hash, c.identity_id, p_credential_id, (a.ch).action, (a.ch).target,
          now() + make_interval(secs => control.setting_int('stepup_grant_ttl_seconds')));
  PERFORM control.audit_append('platform_identity', c.identity_id, c.display_name, 'platform.stepup_succeeded', 'success',
    'session', encode(substring(c.id_hash FROM 1 FOR 8), 'hex'), NULL, NULL,
    jsonb_build_object('action', (a.ch).action, 'target', (a.ch).target, 'credential', left(p_credential_id, 8)));
  RETURN jsonb_build_object('ok', true, 'action', (a.ch).action, 'target', (a.ch).target);
END
$$;

-- Lock order for anything that changes an operator's credentials: IDENTITY row first, then the session row
-- (session_resolve). Taken with FOR NO KEY UPDATE so FK key-share locks from concurrent logins/step-ups do not
-- conflict. Without this, two sessions revoking each other's passkeys deadlock.
CREATE FUNCTION control.identity_lock_for_session(p_token text) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE v uuid;
BEGIN
  IF p_token IS NULL OR p_token !~ '^[0-9a-f]{64}$' THEN RETURN; END IF;
  SELECT identity_id INTO v FROM control.sessions WHERE id_hash = control.sha(p_token);
  IF v IS NOT NULL THEN
    PERFORM 1 FROM control.platform_identities WHERE id = v FOR NO KEY UPDATE;
  END IF;
END
$$;

-- ------------------------------------------------------------ credential lifecycle
CREATE FUNCTION control.api_credential_list(p_token text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE c control.session_ctx := control.session_resolve(p_token); v_current text;
BEGIN
  IF c.identity_id IS NULL THEN RETURN control.err('UNAUTHENTICATED'); END IF;
  SELECT credential_id INTO v_current FROM control.sessions WHERE id_hash = c.id_hash;
  RETURN jsonb_build_object('ok', true, 'credentials',
    (SELECT coalesce(jsonb_agg(jsonb_build_object('id', w.id, 'nickname', w.nickname, 'created_via', w.created_via,
        'created_at', w.created_at, 'last_used_at', w.last_used_at, 'disabled_at', w.disabled_at,
        'disabled_reason', w.disabled_reason, 'fingerprint', left(w.credential_id, 8),
        'current', w.credential_id = v_current) ORDER BY w.created_at), '[]'::jsonb)
       FROM control.webauthn_credentials w WHERE w.identity_id = c.identity_id));
END
$$;

CREATE FUNCTION control.api_credential_add_begin(p_token text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE c control.session_ctx; v_code text;
BEGIN
  PERFORM control.identity_lock_for_session(p_token);
  c := control.session_resolve(p_token);
  IF c.identity_id IS NULL THEN RETURN control.err('UNAUTHENTICATED'); END IF;
  IF (SELECT count(*) FROM control.webauthn_credentials WHERE identity_id = c.identity_id AND disabled_at IS NULL)
     >= control.setting_int('max_credentials_per_identity') THEN
    v_code := 'TOO_MANY_CREDENTIALS';
  ELSIF NOT control.stepup_consume(c, 'credential_add', c.identity_id::text) THEN
    v_code := 'STEPUP_REQUIRED';
  END IF;
  IF v_code IS NOT NULL THEN
    PERFORM control.audit_append('platform_identity', c.identity_id, c.display_name, 'platform.credential_add_failed',
      'denied', 'platform_identity', c.identity_id::text, NULL, v_code, '{}'::jsonb);
    RETURN control.err(v_code);
  END IF;
  RETURN jsonb_build_object('ok', true,
    'challenge', control.challenge_issue('register_add', c.identity_id, c.id_hash, 'credential_add', c.identity_id::text),
    'identity_id', c.identity_id, 'email', c.email, 'display_name', c.display_name,
    'exclude_credential_ids', (SELECT coalesce(jsonb_agg(credential_id), '[]'::jsonb) FROM control.webauthn_credentials
                                WHERE identity_id = c.identity_id AND disabled_at IS NULL));
END
$$;

CREATE FUNCTION control.api_credential_add_complete(p_token text, p_attestation bytea, p_client_data bytea, p_nickname text)
RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE c control.session_ctx; reg record; v_cred uuid;
BEGIN
  PERFORM control.identity_lock_for_session(p_token);
  c := control.session_resolve(p_token);
  IF c.identity_id IS NULL THEN RETURN control.err('UNAUTHENTICATED'); END IF;
  reg := control.wa_registration('register_add', p_attestation, p_client_data);
  IF reg.err IS NULL AND ((reg.ch).identity_id IS DISTINCT FROM c.identity_id
                          OR (reg.ch).session_id_hash IS DISTINCT FROM c.id_hash) THEN
    reg.err := 'INVALID_CHALLENGE';
  END IF;
  IF reg.err IS NULL AND (SELECT count(*) FROM control.webauthn_credentials
                           WHERE identity_id = c.identity_id AND disabled_at IS NULL)
                         >= control.setting_int('max_credentials_per_identity') THEN
    reg.err := 'TOO_MANY_CREDENTIALS';
  END IF;
  IF reg.err IS NULL THEN
    BEGIN
      INSERT INTO control.webauthn_credentials (identity_id, credential_id, public_key, sign_count, nickname, created_via)
      VALUES (c.identity_id, reg.cred_id, reg.cose, reg.sign_count,
              nullif(left(btrim(coalesce(p_nickname, '')), 60), ''), 'added')
      RETURNING id INTO v_cred;
    EXCEPTION WHEN unique_violation OR check_violation THEN
      reg.err := 'INVALID_CREDENTIAL';
    END;
  END IF;
  IF reg.err IS NOT NULL THEN
    PERFORM control.audit_append('platform_identity', c.identity_id, c.display_name, 'platform.credential_add_failed',
      'denied', 'platform_identity', c.identity_id::text, NULL, reg.err, '{}'::jsonb);
    RETURN control.err(reg.err);
  END IF;
  PERFORM control.audit_append('platform_identity', c.identity_id, c.display_name, 'platform.credential_added', 'success',
    'credential', v_cred::text, NULL, NULL, jsonb_build_object('fingerprint', left(reg.cred_id, 8)));
  RETURN jsonb_build_object('ok', true, 'credential', v_cred);
END
$$;

CREATE FUNCTION control.api_credential_revoke(p_token text, p_credential uuid) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE c control.session_ctx; w control.webauthn_credentials; v_code text;
        v_sessions integer; v_self boolean;
BEGIN
  PERFORM control.identity_lock_for_session(p_token);
  c := control.session_resolve(p_token);
  IF c.identity_id IS NULL THEN RETURN control.err('UNAUTHENTICATED'); END IF;
  -- (identity row already locked above: every add/revoke for this identity is serialised, so concurrent
  --  revocations cannot remove the last two passkeys.)
  SELECT * INTO w FROM control.webauthn_credentials WHERE id = p_credential AND identity_id = c.identity_id;
  IF w.id IS NULL OR w.disabled_at IS NOT NULL THEN
    v_code := 'NOT_FOUND';
  ELSIF (SELECT count(*) FROM control.webauthn_credentials
          WHERE identity_id = c.identity_id AND disabled_at IS NULL AND id <> w.id) < 1 THEN
    v_code := 'LAST_CREDENTIAL';
  ELSIF NOT control.stepup_consume(c, 'credential_revoke', w.id::text) THEN
    v_code := 'STEPUP_REQUIRED';
  END IF;
  IF v_code IS NOT NULL THEN
    PERFORM control.audit_append('platform_identity', c.identity_id, c.display_name, 'platform.credential_revoke_refused',
      'denied', 'credential', p_credential::text, NULL, v_code, '{}'::jsonb);
    RETURN control.err(v_code);
  END IF;
  UPDATE control.webauthn_credentials SET disabled_at = now(), disabled_reason = 'revoked', disabled_by = c.identity_id
   WHERE id = w.id;
  UPDATE control.sessions SET revoked_at = now(), revoke_reason = 'credential_revoked'
   WHERE identity_id = c.identity_id AND credential_id = w.credential_id AND revoked_at IS NULL;
  GET DIAGNOSTICS v_sessions = ROW_COUNT;
  v_self := NOT EXISTS (SELECT 1 FROM control.sessions WHERE id_hash = c.id_hash AND revoked_at IS NULL);
  PERFORM control.audit_append('platform_identity', c.identity_id, c.display_name, 'platform.credential_revoked', 'success',
    'credential', w.id::text, NULL, NULL,
    jsonb_build_object('fingerprint', left(w.credential_id, 8), 'sessions_revoked', v_sessions));
  RETURN jsonb_build_object('ok', true, 'sessions_revoked', v_sessions, 'current_session_ended', v_self);
END
$$;

-- ------------------------------------------------------------ recovery (two people; no single-person path)
-- Host-only: the infrastructure owner records that an operator lost all passkeys. Grants nothing by itself.
CREATE FUNCTION control.host_recovery_request(p_email text, p_reason text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE i control.platform_identities; v_id uuid;
BEGIN
  SELECT * INTO i FROM control.platform_identities WHERE email = lower(btrim(p_email)) AND state = 'active';
  IF i.id IS NULL THEN RETURN control.err('NOT_FOUND'); END IF;
  UPDATE control.recovery_requests SET state = 'cancelled'
   WHERE subject_id = i.id AND state IN ('pending', 'approved') AND expires_at <= now();
  BEGIN
    INSERT INTO control.recovery_requests (subject_id, reason, expires_at)
    VALUES (i.id, btrim(p_reason), now() + make_interval(secs => control.setting_int('recovery_request_ttl_seconds')))
    RETURNING id INTO v_id;
  EXCEPTION WHEN unique_violation THEN RETURN control.err('ALREADY_OPEN');
            WHEN check_violation OR not_null_violation THEN RETURN control.err('REASON_REQUIRED');
  END;
  PERFORM control.audit_append('cli', NULL, 'host-recovery', 'platform.recovery_requested', 'success',
    'recovery_request', v_id::text, NULL, NULL, jsonb_build_object('subject', i.id));
  RETURN jsonb_build_object('ok', true, 'request_id', v_id);
END
$$;

CREATE FUNCTION control.api_recovery_list(p_token text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE c control.session_ctx := control.session_resolve(p_token);
BEGIN
  IF c.identity_id IS NULL THEN RETURN control.err('UNAUTHENTICATED'); END IF;
  IF c.role <> 'owner' THEN RETURN control.err('FORBIDDEN'); END IF;
  RETURN jsonb_build_object('ok', true, 'requests',
    (SELECT coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'subject_display_name', i.display_name,
        'subject_is_you', r.subject_id = c.identity_id, 'reason', r.reason, 'state', r.state,
        'requested_at', r.requested_at, 'expires_at', r.expires_at) ORDER BY r.requested_at DESC), '[]'::jsonb)
       FROM control.recovery_requests r JOIN control.platform_identities i ON i.id = r.subject_id
      WHERE r.state IN ('pending', 'approved') AND r.expires_at > now()));
END
$$;

-- A DIFFERENT active owner approves with a step-up bound to this request; returns a one-time enrolment token
-- (30 min) that the approver hands to the subject out of band.
CREATE FUNCTION control.api_recovery_approve(p_token text, p_request uuid) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE c control.session_ctx := control.session_resolve(p_token); r control.recovery_requests; v_code text; v_tok text;
BEGIN
  IF c.identity_id IS NULL THEN RETURN control.err('UNAUTHENTICATED'); END IF;
  SELECT * INTO r FROM control.recovery_requests WHERE id = p_request FOR UPDATE;
  IF c.role <> 'owner' THEN v_code := 'FORBIDDEN';
  ELSIF r.id IS NULL OR r.state <> 'pending' OR r.expires_at <= now() THEN v_code := 'NOT_FOUND';
  ELSIF r.subject_id = c.identity_id THEN v_code := 'SELF_APPROVAL_FORBIDDEN';
  ELSIF NOT EXISTS (SELECT 1 FROM control.platform_identities WHERE id = r.subject_id AND state = 'active') THEN v_code := 'NOT_FOUND';
  ELSIF NOT control.stepup_consume(c, 'recovery_approve', r.id::text) THEN v_code := 'STEPUP_REQUIRED';
  END IF;
  IF v_code IS NOT NULL THEN
    PERFORM control.audit_append('platform_identity', c.identity_id, c.display_name, 'platform.recovery_refused', 'denied',
      'recovery_request', p_request::text, NULL, v_code, '{}'::jsonb);
    RETURN control.err(v_code);
  END IF;
  v_tok := control.new_secret();
  INSERT INTO control.enrolment_tokens (token_hash, identity_id, purpose, expires_at, recovery_request_id)
  VALUES (control.sha(v_tok), r.subject_id, 'recovery',
          now() + make_interval(secs => control.setting_int('recovery_token_ttl_seconds')), r.id);
  UPDATE control.recovery_requests SET state = 'approved', approved_by = c.identity_id, approved_at = now() WHERE id = r.id;
  PERFORM control.audit_append('platform_identity', c.identity_id, c.display_name, 'platform.recovery_approved', 'success',
    'recovery_request', r.id::text, NULL, NULL, jsonb_build_object('subject', r.subject_id));
  RETURN jsonb_build_object('ok', true, 'enrolment_token', v_tok,
                            'expires_in_seconds', control.setting_int('recovery_token_ttl_seconds'));
END
$$;

RESET ROLE;

-- ============================================================ control_definer functions that used step-up
CREATE OR REPLACE FUNCTION control.authorize(c control.session_ctx, p_roles text[], p_need_stepup boolean,
                                             p_action_label text, p_request_id uuid)
RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE v_code text;
BEGIN
  IF c.identity_id IS NULL THEN RETURN control.err('UNAUTHENTICATED'); END IF;
  IF NOT (c.role = ANY (p_roles)) THEN
    v_code := 'FORBIDDEN';
  ELSIF p_need_stepup AND NOT control.stepup_consume(c, p_action_label, coalesce(p_request_id::text, '-')) THEN
    v_code := 'STEPUP_REQUIRED';
  END IF;
  IF v_code IS NULL THEN RETURN NULL; END IF;
  PERFORM control.audit_append('platform_identity', c.identity_id, c.display_name, 'platform.access_denied', 'denied',
    'api', p_action_label, p_request_id, v_code, '{}'::jsonb);
  RETURN control.err(v_code);
END
$$;
ALTER FUNCTION control.authorize(control.session_ctx, text[], boolean, text, uuid) OWNER TO control_definer;

CREATE OR REPLACE FUNCTION control.api_tenant_transition(p_token text, p_tenant_id uuid, p_to_state text,
                                                         p_reason_code text, p_note text, p_request_id uuid)
RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = control, pg_temp AS $$
DECLARE
  c control.session_ctx := control.session_resolve(p_token);
  t control.tenants; x control.tenant_transitions; v_code text; v_seq bigint;
  v_prior control.request_results; v_result jsonb;
BEGIN
  IF c.identity_id IS NULL THEN RETURN control.err('UNAUTHENTICATED'); END IF;
  IF p_request_id IS NULL THEN RETURN control.err('REQUEST_ID_REQUIRED'); END IF;
  PERFORM pg_advisory_xact_lock(203, hashtext(p_request_id::text));
  SELECT * INTO v_prior FROM control.request_results WHERE request_id = p_request_id;
  IF v_prior.request_id IS NOT NULL THEN
    IF v_prior.identity_id <> c.identity_id OR v_prior.action <> 'tenant_transition' THEN
      RETURN control.err('REQUEST_ID_CONFLICT');
    END IF;
    RETURN v_prior.result || jsonb_build_object('replayed', true);
  END IF;
  SELECT * INTO t FROM control.tenants WHERE id = p_tenant_id FOR UPDATE;
  IF t.id IS NULL THEN RETURN control.err('NOT_FOUND'); END IF;
  SELECT * INTO x FROM control.tenant_transitions WHERE from_state = t.status AND to_state = p_to_state;
  -- Step-up is checked LAST so that a grant is consumed only by an otherwise valid request.
  IF x.from_state IS NULL THEN v_code := 'TRANSITION_NOT_ALLOWED';
  ELSIF NOT x.available THEN v_code := 'NOT_AVAILABLE_IN_FOUNDATION';
  ELSIF NOT (c.role = ANY (x.allowed_roles)) THEN v_code := 'FORBIDDEN';
  ELSIF x.requires_reason AND (p_reason_code IS NULL
        OR p_reason_code NOT IN ('owner_request', 'abuse', 'security', 'notice', 'test', 'other')
        OR length(btrim(coalesce(p_note, ''))) < 10 OR length(p_note) > 500) THEN v_code := 'REASON_REQUIRED';
  ELSIF x.requires_stepup AND NOT control.stepup_consume(c, 'tenant_transition', t.id::text || ':' || p_to_state) THEN
    v_code := 'STEPUP_REQUIRED';
  END IF;
  IF v_code IS NOT NULL THEN
    PERFORM control.audit_append('platform_identity', c.identity_id, c.display_name, 'tenant.transition_refused',
      'denied', 'tenant', t.id::text, p_request_id, v_code,
      jsonb_build_object('from', t.status, 'to', p_to_state, 'synthetic', true));
    RETURN control.err(v_code);
  END IF;
  UPDATE control.tenants SET status = p_to_state, status_reason = p_reason_code, status_note = p_note, status_changed_at = now()
   WHERE id = t.id;
  v_seq := control.audit_append('platform_identity', c.identity_id, c.display_name, 'tenant.transitioned', 'success',
    'tenant', t.id::text, p_request_id, p_reason_code, jsonb_build_object('from', t.status, 'to', p_to_state, 'synthetic', true));
  INSERT INTO control.tenant_status_history (tenant_id, from_state, to_state, reason_code, note, actor_id, audit_seq)
  VALUES (t.id, t.status, p_to_state, p_reason_code, p_note, c.identity_id, v_seq);
  v_result := jsonb_build_object('ok', true, 'tenant_id', t.id, 'from', t.status, 'to', p_to_state, 'audit_seq', v_seq);
  INSERT INTO control.request_results (request_id, identity_id, action, result)
  VALUES (p_request_id, c.identity_id, 'tenant_transition', v_result);
  RETURN v_result;
END
$$;
ALTER FUNCTION control.api_tenant_transition(text, uuid, text, text, text, uuid) OWNER TO control_definer;

-- ============================================================ upgrade effects
UPDATE control.webauthn_credentials SET disabled_at = now(), disabled_reason = 'unsupported_key_format'
 WHERE disabled_at IS NULL AND control.cose_es256_xy(public_key) IS NULL;
DO $up$
DECLARE n integer;
BEGIN
  UPDATE control.sessions SET revoked_at = now(), revoke_reason = 'upgrade' WHERE revoked_at IS NULL;
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM control.audit_append('system', NULL, 'migration-205', 'platform.sessions_revoked', 'success',
    NULL, NULL, NULL, 'UPGRADE', jsonb_build_object('sessions_revoked', n));
END
$up$;

-- ============================================================ grants
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA control FROM PUBLIC;
GRANT EXECUTE ON FUNCTION control.session_resolve(text) TO control_definer;
GRANT EXECUTE ON FUNCTION control.stepup_consume(control.session_ctx, text, text) TO control_definer;
GRANT EXECUTE ON FUNCTION
  control.api_contract_version(),
  control.api_enrol_begin(text),
  control.api_enrol_complete(text, bytea, bytea, text),
  control.api_login_begin(),
  control.api_credential_lookup(text),
  control.api_login_complete(text, bytea, bytea, bytea),
  control.api_auth_failed(text, text, text, text),
  control.api_session_get(text),
  control.api_session_revoke(text),
  control.api_stepup_begin(text, text, text),
  control.api_stepup_complete(text, text, bytea, bytea, bytea),
  control.api_credential_list(text),
  control.api_credential_add_begin(text),
  control.api_credential_add_complete(text, bytea, bytea, text),
  control.api_credential_revoke(text, uuid),
  control.api_recovery_list(text),
  control.api_recovery_approve(text, uuid)
TO control_app;
-- host_bootstrap_owner and host_recovery_request: deliberately NO grant (superuser on the host only).
REVOKE CREATE ON SCHEMA control FROM control_auth;
